using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerResourceType]
public class ConfigResources
{
    /// <summary>
    /// Returns the current application configuration as a JSON resource.
    /// </summary>
    [McpServerResource(UriTemplate = "config://app", Name = "app-config",
        MimeType = "application/json", Title = "Application Configuration")]
    [Description("Current application configuration including feature flags and limits.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            version = "1.0.0",
            environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            features = new { enableBetaFeatures = false, maxRequestsPerMinute = 100 },
            supportedRegions = new[] { "us-east-1", "eu-west-1", "ap-southeast-1" }
        };

        return System.Text.Json.JsonSerializer.Serialize(config,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>
    /// Returns configuration for a specific region.
    /// </summary>
    [McpServerResource(UriTemplate = "config://regions/{region}", Name = "region-config",
        MimeType = "application/json", Title = "Region Configuration")]
    [Description("Configuration for a specific deployment region.")]
    public static string GetRegionConfig(string region)
    {
        var regionConfig = new
        {
            region,
            endpoint = $"https://api.{region}.example.com",
            isPrimary = region == "us-east-1",
            replicaCount = region == "us-east-1" ? 3 : 2
        };

        return System.Text.Json.JsonSerializer.Serialize(regionConfig,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerToolType]
public class WeatherTools
{
    [McpServerTool(Name = "get-weather"), Description("Gets the current weather for a city.")]
    public static string GetWeather(string city)
    {
        // Stubbed response for demonstration
        return $"The weather in {city} is 72°F and sunny.";
    }
}

